// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint64 t1, uint64 t2) public {
        vm.assume(t1 > 0 && t2 > t1);
        address actor = makeAddr("actor");

        vm.warp(t1);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call should succeed");
        assertEq(c.pastBlockTime(), t1);

        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2, "second call should succeed");

        // General rule: after a successful fallback call at time t2, the stored
        // timestamp equals t2. The mutant never updates it, so it stays t1.
        assertTrue(c.pastBlockTime() == t2, "pastBlockTime must track latest call timestamp");
    }
}
